// For "-5", parse as -5 (digit found) -> numeric valid, but then value <=0 => positive error.
// For "0", value 0 => positive error.
// For " 1", valid.
// For "" invalid.

int parse_int_prefix(const char *s, long *out) {
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    int sign = 1;
    if (*p == '+' || *p == '-') {
        if (*p == '-') sign = -1;
        p++;
    }
    if (!isdigit((unsigned char)*p)) return 0; // no digit
    long val = 0;
    while (isdigit((unsigned char)*p)) {
        val = val * 10 + (*p - '0');
        p++;
    }
    *out = sign * val;
    return 1;
}

