                }else{
                    i++;
                    continue;
                }
            }else if (opt->type==OPT_REQ){
                const char *val=NULL;
                if (has_eq){
                    val=opt_arg;
                }else{
                    if (i+1>=argc){
                        fprintf(stderr,"%s: option '--%s' requires an argument\n",progname,opt->canonical);
                        return 1;
                    }
                    val=argv[i+1];
                    i++;
                }
                if (opt->action==ACT_DELAY){
                    if (!validate_delay(val)){
                        fprintf(stderr,"Error: invalid delay value \"%s\".\n",val);
                        return 1;
                    }
                }else if (opt->action==ACT_FILTER){
                    if (!validate_filter(val)){
                        fprintf(stderr,"Error: invalid filter value \"%s\".\n",val);
                        return 1;
                    }
                }else if (opt->action==ACT_MAX_ITER){
                    int inv,nonpos;
                    if (!validate_max_iter(val,&inv,&nonpos)){
                        if (inv) fprintf(stderr,"Error: invalid maximum iteration count \"%s\".\n",val);
                        else fprintf(stderr,"Error: maximum iteration count must be positive.\n");
                        return 1;
                    }
                }else if (opt->action==ACT_PID){
                    // no validation, even empty allowed via --pid= ? Actually --pid= empty is allowed (we saw CURSES). So no error.
                }else if (opt->action==ACT_SORT){
                    int res=is_valid_sort_key(val);
                    if (res==2){
                        printf("%s",sort_help_text);
                        return 0;
                    }else if (res==0){
                        fprintf(stderr,"Error: invalid column \"%s\".\n",val);
                        return 1;
                    }
                }
                i++;
                continue;
            }else if (opt->type==OPT_OPT){
                const char *val=NULL;
                int has_val=0;
                if (has_eq){
                    val=opt_arg;
                    has_val=1;
                }else{
                    if (i+1<argc){
                        const char *next=argv[i+1];
                        if (next[0]=='\0'){
                            has_val=0;
                        }else if (next[0]=='-'){
                            has_val=0;
                        }else{
                            val=next;
                            has_val=1;
                            i++;
                        }
                    }
                }
                if (opt->action==ACT_HIGHLIGHT){
                    if (has_val){
                        if (!validate_delay(val)){
                            fprintf(stderr,"Error: invalid highlight delay value \"%s\".\n",val);
                            return 1;
                        }
                    }
                    i++;
                    continue;
                }else if (opt->action==ACT_USER){
                    if (has_val){
                        int res=validate_user(val);
                        if (res!=1){
                            fprintf(stderr,"Error: invalid user \"%s\".\n",val);
                            return 1;
                        }
                    }
                    i++;
                    continue;
                }
            }
        }else{
            // short cluster
            char *p=arg+1;
            int consumed_next=0;
            while (*p){
                char c=*p;
                if (c=='C'){
                    p++; continue;
                }else if (c=='d'){
                    const char *val=NULL;
                    if (*(p+1)!='\0'){
                        val=p+1;
                        p="";
                    }else{
                        if (i+1>=argc){
                            fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c);
                            return 1;
                        }
                        val=argv[i+1];
                        consumed_next=1;
                        break;
                    }
                    if (!validate_delay(val)){
                        fprintf(stderr,"Error: invalid delay value \"%s\".\n",val);
                        return 1;
                    }
                    break;
                }else if (c=='F'){
                    const char *val=NULL;
                    if (*(p+1)!='\0'){
                        val=p+1;
                        p="";
                    }else{
                        if (i+1>=argc){
                            fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c);
                            return 1;
                        }
                        val=argv[i+1];
                        consumed_next=1;
                        break;
                    }
                    if (!validate_filter(val)){
                        fprintf(stderr,"Error: invalid filter value \"%s\".\n",val);
                        return 1;
                    }
                    break;
                }else if (c=='h'){
                    printf("%s",help_text);
                    return 0;
                }else if (c=='H'){
                    const char *val=NULL;
                    int has_val=0;
                    if (*(p+1)!='\0'){
                        val=p+1;
                        has_val=1;
                        p="";
                    }else{
                        if (i+1<argc){
                            const char *next=argv[i+1];
                            if (next[0]=='\0'){
                                has_val=0;
                            }else if (next[0]=='-'){
                                has_val=0;
                            }else{
                                val=next;
                                has_val=1;
                                consumed_next=1;
                            }
                        }
                    }
                    if (has_val){
                        if (!validate_delay(val)){
                            fprintf(stderr,"Error: invalid highlight delay value \"%s\".\n",val);
                            return 1;
                        }
                    }
                    break;
                }else if (c=='M'){
                    p++; continue;
                }else if (c=='n'){
                    const char *val=NULL;
                    if (*(p+1)!='\0'){
                        val=p+1;
                        p="";
                    }else{
                        if (i+1>=argc){
                            fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c);
                            return 1;
                        }
                        val=argv[i+1];
                        consumed_next=1;
                        break;
                    }
                    int inv,nonpos;
                    if (!validate_max_iter(val,&inv,&nonpos)){
                        if (inv) fprintf(stderr,"Error: invalid maximum iteration count \"%s\".\n",val);
                        else fprintf(stderr,"Error: maximum iteration count must be positive.\n");
                        return 1;
                    }
                    break;
                }else if (c=='p'){
                    const char *val=NULL;
                    if (*(p+1)!='\0'){
                        val=p+1;
                        p="";
                    }else{
                        if (i+1>=argc){
                            fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c);
                            return 1;
                        }
                        val=argv[i+1];
                        consumed_next=1;
                        break;
                    }
                    break;
                }else if (c=='s'){
                    const char *val=NULL;
                    if (*(p+1)!='\0'){
                        val=p+1;
                        p="";
                    }else{
                        if (i+1>=argc){
                            fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c);
                            return 1;
                        }
                        val=argv[i+1];
                        consumed_next=1;
                        break;
                    }
                    int res=is_valid_sort_key(val);
                    if (res==2){
                        printf("%s",sort_help_text);
                        return 0;
                    }else if (res==0){
                        fprintf(stderr,"Error: invalid column \"%s\".\n",val);
                        return 1;
                    }
                    break;
                }else if (c=='t'){
                    p++; continue;
                }else if (c=='u'){
                    const char *val=NULL;
                    int has_val=0;
                    if (*(p+1)!='\0'){
                        val=p+1;
                        has_val=1;
                        p="";
                    }else{
                        if (i+1<argc){
                            const char *next=argv[i+1];
                            if (next[0]=='\0'){
                                has_val=0;
                            }else if (next[0]=='-'){
                                has_val=0;
                            }else{
                                val=next;
                                has_val=1;
                                consumed_next=1;
                            }
                        }
                    }
                    if (has_val){
                        int res=validate_user(val);
                        if (res!=1){
                            fprintf(stderr,"Error: invalid user \"%s\".\n",val);
                            return 1;
                        }
                    }
                    break;
                }else if (c=='U'){
                    p++; continue;
                }else if (c=='V'){
                    printf("%s",version_text);
                    return 0;
                }else{
                    fprintf(stderr,"%s: invalid option -- '%c'\n",progname,c);
                    return 1;
                }
            }
            if (consumed_next) i++;
            i++;
            continue;
        }
    }

    const char *term=getenv("TERM");
    if (!term || strcmp(term,"unknown")==0 || strlen(term)==0){
        fprintf(stderr,"Error opening terminal: unknown.\n");
        return 1;
    }
    return 0;
}
