const char *progname;

int validate_delay(const char *s){
    if (!s) return 0;
    const char *p=s;
    while (isspace((unsigned char)*p)) p++;
    if (*p=='+'||*p=='-') p++;
    if (!isdigit((unsigned char)*p)) return 0;
    while (isdigit((unsigned char)*p)) p++;
    return 1;
}
int parse_int_prefix(const char *s, long *out){
    const char *p=s;
    while (isspace((unsigned char)*p)) p++;
    int sign=1;
    if (*p=='+'||*p=='-'){ if (*p=='-') sign=-1; p++; }
    if (!isdigit((unsigned char)*p)) return 0;
    long v=0;
    while (isdigit((unsigned char)*p)){ v=v*10+(*p-'0'); p++; }
    *out=sign*v;
    return 1;
}
int validate_filter(const char *s){ return s && strlen(s)!=0; }
int validate_max_iter(const char *s, int *inv, int *nonpos){
    long v;
    *inv=0; *nonpos=0;
    if (!s || strlen(s)==0){ *inv=1; return 0; }
    if (!parse_int_prefix(s,&v)){ *inv=1; return 0; }
    if (v<=0){ *nonpos=1; return 0; }
    return 1;
}
int is_valid_sort_key(const char *s){
    if (!s) return 0;
    if (strcmp(s,"help")==0) return 2;
    for (int i=0; valid_keys[i]; i++) if (strcmp(s,valid_keys[i])==0) return 1;
    return 0;
}
int validate_user(const char *s){
    if (!s) return -1;
    // check numeric pattern ^[ \t]*[+-]?[0-9]+$
    const char *p=s;
    while (*p && isspace((unsigned char)*p)) p++;
    const char *after_spaces = p;
    if (*p=='+'||*p=='-') p++;
    const char *digit_start=p;
    while (*p && isdigit((unsigned char)*p)) p++;
    if (digit_start!=p && *p=='\0'){
        long v;
        if (parse_int_prefix(s,&v)){
            if (v<0) return -1;
            return 1;
        }
        return -1;
    }
    // non-numeric: if any whitespace in original, invalid
    for (const char *q=s; *q; q++) if (isspace((unsigned char)*q)) return -1;
    struct passwd *pw=getpwnam(s);
    if (pw) return 1;
    return -1;
}

// long opt find
LongOpt *find_long_opt(const char *name, int *ambiguous, const char **matched_canonical, char *poss_buf, size_t poss_size){
    *ambiguous=0;
    if (matched_canonical) *matched_canonical=NULL;
    // exact
    for (int i=0; long_opts[i].name; i++) if (strcmp(long_opts[i].name,name)==0){
        if (matched_canonical) *matched_canonical=long_opts[i].canonical;
        return &long_opts[i];
    }
    // prefix
    LongOpt *candidates[32];
    int cnt=0;
    for (int i=0; long_opts[i].name; i++){
        if (strncmp(long_opts[i].name,name,strlen(name))==0){
            candidates[cnt++]=&long_opts[i];
        }
    }
    if (cnt==0) return NULL;
    // distinct actions
    int distinct_actions[32];
    LongOpt *first_for_action[32];
    int distinct_cnt=0;
    for (int i=0;i<cnt;i++){
        int act=candidates[i]->action;
        int found=0;
        for (int j=0;j<distinct_cnt;j++) if (distinct_actions[j]==act){ found=1; break; }
        if (!found){ distinct_actions[distinct_cnt]=act; first_for_action[distinct_cnt]=candidates[i]; distinct_cnt++; }
    }
    if (distinct_cnt==1){
        if (matched_canonical) *matched_canonical=first_for_action[0]->canonical;
        return first_for_action[0];
    } else {
        *ambiguous=1;
        if (poss_buf){
            poss_buf[0]='\0';
            for (int i=0;i<cnt;i++){
                if (i>0) strncat(poss_buf," ",poss_size-1-strlen(poss_buf));
                char tmp[256];
                snprintf(tmp,sizeof(tmp),"'--%s'",candidates[i]->name);
                strncat(poss_buf,tmp,poss_size-1-strlen(poss_buf));
            }
        }
        return NULL;
    }
}

int main(int argc, char *argv[]){
    progname=argv[0];
    int i=1;
    while (i<argc){
        char *arg=argv[i];
        if (arg[0]!='-' || strcmp(arg,"-")==0){
            fprintf(stderr,"Error: unsupported non-option ARGV-elements: %s\n",arg);
            return 1;
        }
        if (arg[1]=='-'){
            char *eq=strchr(arg,'=');
            char namebuf[256];
            const char *opt_name;
            const char *opt_arg=NULL;
            int has_eq=0;
            if (eq){
                size_t len=eq-(arg+2);
                if (len>=sizeof(namebuf)) len=sizeof(namebuf)-1;
                strncpy(namebuf,arg+2,len);
                namebuf[len]='\0';
                opt_name=namebuf;
                opt_arg=eq+1;
                has_eq=1;
            }else{
                opt_name=arg+2;
            }
            if (strlen(opt_name)==0){
                // "--" case
                // Check if it's exactly "--"? Then treat rest as non-options
                if (strcmp(arg,"--")==0){
                    // next args are non-options -> error first one
                    if (i+1<argc){
                        fprintf(stderr,"Error: unsupported non-option ARGV-elements: %s\n",argv[i+1]);
                        return 1;
                    } else {
                        // no extra, just continue? but original would maybe not error? For simplicity return 0 as curses? But we will treat as error? Actually "--" alone with no extra should be like no args? Let's check original: ./executable -- -h ?
                        // We haven't tested. We'll just treat as if no args left then exit 0 (curses)
                        i++;
                        continue;
                    }
                }
                fprintf(stderr,"%s: unrecognized option '--'\n",progname);
                return 1;
            }
            int ambiguous=0;
            const char *matched_canonical=NULL;
            char poss[1024]="";
            LongOpt *opt=find_long_opt(opt_name,&ambiguous,&matched_canonical,poss,sizeof(poss));
            if (ambiguous){
                fprintf(stderr,"%s: option '--%s' is ambiguous; possibilities: %s\n",progname,opt_name,poss);
                return 1;
            }
            if (!opt){
                fprintf(stderr,"%s: unrecognized option '--%s'\n",progname,opt_name);
                return 1;
            }
            if (opt->type==OPT_FLAG){
                if (has_eq){
                    fprintf(stderr,"%s: option '--%s' doesn't allow an argument\n",progname,opt->canonical);
                    return 1;
                }
                if (opt->action==ACT_HELP){
                    printf("%s",help_text);
                    return 0;
                }else if (opt->action==ACT_VERSION){
                    printf("%s",version_text);
                    return 0;
                }else{
                    i++;
                    continue;
                }
            }else if (opt->type==OPT_REQ){
                const char *val=NULL;
                if (has_eq){
                    val=opt_arg;
                }else{
                    if (i+1>=argc){
                        fprintf(stderr,"%s: option '--%s' requires an argument\n",progname,opt->canonical);
                        return 1;
                    }
                    val=argv[i+1];
                    i++;
                }
                if (opt->action==ACT_DELAY){
                    if (!validate_delay(val)){
                        fprintf(stderr,"Error: invalid delay value \"%s\".\n",val);
                        return 1;
                    }
                }else if (opt->action==ACT_FILTER){
                    if (!validate_filter(val)){
                        fprintf(stderr,"Error: invalid filter value \"%s\".\n",val);
                        return 1;
                    }
                }else if (opt->action==ACT_MAX_ITER){
                    int inv,nonpos;
