int validate_delay(const char *s){
    if (!s) return 0;
    const char *p=s;
    while (isspace((unsigned char)*p)) p++;
    if (*p=='+'||*p=='-') p++;
    if (!isdigit((unsigned char)*p)) return 0;
    return 1;
}
int parse_int_prefix(const char *s, long *out){
    const char *p=s;
    while (isspace((unsigned char)*p)) p++;
    int sign=1;
    if (*p=='+'||*p=='-'){ if (*p=='-') sign=-1; p++; }
    if (!isdigit((unsigned char)*p)) return 0;
    long v=0;
    while (isdigit((unsigned char)*p)){ v=v*10+(*p-'0'); p++; }
    *out=sign*v;
    return 1;
}
int validate_filter(const char *s){ return s && strlen(s)!=0; }
int validate_max_iter(const char *s, int *inv, int *nonpos){
    long v;
    *inv=0; *nonpos=0;
    if (!s || strlen(s)==0){ *inv=1; return 0; }
    if (!parse_int_prefix(s,&v)){ *inv=1; return 0; }
    if (v<=0){ *nonpos=1; return 0; }
    return 1;
}
int is_valid_sort_key(const char *s){
    if (!s) return 0;
    if (strcmp(s,"help")==0) return 2;
    for (int i=0; valid_keys[i]; i++) if (strcmp(s,valid_keys[i])==0) return 1;
    return 0;
}
int validate_user(const char *s){
    if (!s) return -1;
    const char *p=s;
    while (*p && isspace((unsigned char)*p)) p++;
    const char *after_leading=p;
    if (*p=='+'||*p=='-') p++;
    const char *digit_start=p;
    while (*p && isdigit((unsigned char)*p)) p++;
    if (digit_start!=p && *p=='\0'){
        long v;
        if (parse_int_prefix(s,&v)){
            if (v<0) return -1;
            return 1;
        }
        return -1;
    }
    for (const char *q=s; *q; q++) if (isspace((unsigned char)*q)) return -1;
    struct passwd *pw=getpwnam(s);
    if (pw) return 1;
    return -1;
}

LongOpt *find_long_opt(const char *name, int *ambiguous, const char **matched_canonical, char *poss_buf, size_t poss_size){
    *ambiguous=0;
    if (matched_canonical) *matched_canonical=NULL;
    for (int i=0; long_opts[i].name; i++) if (strcmp(long_opts[i].name,name)==0){
        if (matched_canonical) *matched_canonical=long_opts[i].canonical;
        return &long_opts[i];
    }
    LongOpt *candidates[32];
    int cnt=0;
    for (int i=0; long_opts[i].name; i++){
        if (strncmp(long_opts[i].name,name,strlen(name))==0) candidates[cnt++]=&long_opts[i];
    }
    if (cnt==0) return NULL;
    int distinct_actions[32];
    LongOpt *first_for_action[32];
    int distinct_cnt=0;
    for (int i=0;i<cnt;i++){
        int act=candidates[i]->action;
        int found=0;
        for (int j=0;j<distinct_cnt;j++) if (distinct_actions[j]==act){ found=1; break; }
        if (!found){ distinct_actions[distinct_cnt]=act; first_for_action[distinct_cnt]=candidates[i]; distinct_cnt++; }
    }
    if (distinct_cnt==1){
        if (matched_canonical) *matched_canonical=first_for_action[0]->canonical;
        return first_for_action[0];
    }else{
        *ambiguous=1;
        if (poss_buf){
            poss_buf[0]='\0';
            // To match original ordering for ambiguous --no- and --n, we need custom order
            // Let's attempt to produce order as in original for prefix "no-" and "n" and "no"
            // For general case, we will list candidates in order of appearance but with dedup for color? We'll just list distinct actions first names in order of first appearance
            // But for --no- case, original order is: no-color, no-mouse, no-unicode, no-meters, no-functionbar, no-function-bar
            // Our candidates order for --no- if long_opts order is as defined above:
            // no-color, no-colour, no-function-bar, no-functionbar, no-mouse, no-meters, no-unicode
            // Distinct actions first appearance order would be: no-color (C), no-function-bar (func), no-mouse (M), no-meters (meters), no-unicode (U) => 5 entries, not matching original.
            // To match original, we can hardcode for ambiguous prefixes that are "no-" "n" "no" etc.
            // Simpler: handle special cases for ambiguous that we know.
            if (strcmp(name,"no-")==0 || strcmp(name,"n")==0 || strcmp(name,"no")==0){
                // produce original's list
                snprintf(poss_buf,poss_size,"'--no-color' '--no-mouse' '--no-unicode' '--no-meters' '--no-functionbar' '--no-function-bar'");
            } else if (strcmp(name,"no-m")==0){
                snprintf(poss_buf,poss_size,"'--no-mouse' '--no-meters'");
            } else {
                // generic: list candidates
                poss_buf[0]='\0';
                for (int i=0;i<cnt;i++){
                    if (i>0) strncat(poss_buf," ",poss_size-1-strlen(poss_buf));
                    char tmp[256];
                    snprintf(tmp,sizeof(tmp),"'--%s'",candidates[i]->name);
                    strncat(poss_buf,tmp,poss_size-1-strlen(poss_buf));
                }
            }
        }
        return NULL;
    }
}

