        }
        if (arg[1]=='-'){
            char *eq=strchr(arg,'=');
            char namebuf[256];
            const char *opt_name;
            const char *opt_arg=NULL;
            int has_eq=0;
            if (eq){
                size_t len=eq-(arg+2);
                if (len>=sizeof(namebuf)) len=sizeof(namebuf)-1;
                strncpy(namebuf,arg+2,len);
                namebuf[len]='\0';
                opt_name=namebuf;
                opt_arg=eq+1;
                has_eq=1;
            }else{
                opt_name=arg+2;
            }
            if (strlen(opt_name)==0){
                if (strcmp(arg,"--")==0){
                    if (i+1<argc){
                        fprintf(stderr,"Error: unsupported non-option ARGV-elements: %s\n",argv[i+1]);
                        return 1;
                    }else{
                        i++;
                        continue;
                    }
                }
                fprintf(stderr,"%s: unrecognized option '--'\n",progname);
                return 1;
            }
            int ambiguous=0;
            const char *matched_canonical=NULL;
            char poss[1024]="";
            LongOpt *opt=find_long_opt(opt_name,&ambiguous,&matched_canonical,poss,sizeof(poss));
            if (ambiguous){
                fprintf(stderr,"%s: option '--%s' is ambiguous; possibilities: %s\n",progname,opt_name,poss);
                return 1;
            }
            if (!opt){
                fprintf(stderr,"%s: unrecognized option '--%s'\n",progname,opt_name);
                return 1;
            }
            if (opt->type==OPT_FLAG){
                if (has_eq){
                    fprintf(stderr,"%s: option '--%s' doesn't allow an argument\n",progname,opt->canonical);
                    return 1;
                }
                if (opt->action==ACT_HELP){ printf("%s",help_text); return 0; }
                else if (opt->action==ACT_VERSION){ printf("%s",version_text); return 0; }
                else { i++; continue; }
            }else if (opt->type==OPT_REQ){
                const char *val=NULL;
                if (has_eq) val=opt_arg;
                else{
                    if (i+1>=argc){ fprintf(stderr,"%s: option '--%s' requires an argument\n",progname,opt->canonical); return 1; }
                    val=argv[i+1];
                    i++;
                }
                if (opt->action==ACT_DELAY){ if (!validate_delay(val)){ fprintf(stderr,"Error: invalid delay value \"%s\".\n",val); return 1; } }
                else if (opt->action==ACT_FILTER){ if (!validate_filter(val)){ fprintf(stderr,"Error: invalid filter value \"%s\".\n",val); return 1; } }
                else if (opt->action==ACT_MAX_ITER){ int inv,nonpos; if (!validate_max_iter(val,&inv,&nonpos)){ if (inv) fprintf(stderr,"Error: invalid maximum iteration count \"%s\".\n",val); else fprintf(stderr,"Error: maximum iteration count must be positive.\n"); return 1; } }
                else if (opt->action==ACT_SORT){ int res=is_valid_sort_key(val); if (res==2){ printf("%s",sort_help_text); return 0; } else if (res==0){ fprintf(stderr,"Error: invalid column \"%s\".\n",val); return 1; } }
                i++;
                continue;
            }else if (opt->type==OPT_OPT){
                const char *val=NULL;
                int has_val=0;
                if (has_eq){ val=opt_arg; has_val=1; }
                else{
                    if (i+1<argc){
                        const char *next=argv[i+1];
                        if (next[0]=='\0') has_val=0;
                        else if (next[0]=='-') has_val=0;
                        else { val=next; has_val=1; i++; }
                    }
                }
                if (opt->action==ACT_HIGHLIGHT){
                    if (has_val && !validate_delay(val)){ fprintf(stderr,"Error: invalid highlight delay value \"%s\".\n",val); return 1; }
                    i++;
                    continue;
                }else if (opt->action==ACT_USER){
                    if (has_val){
                        int res=validate_user(val);
                        if (res!=1){ fprintf(stderr,"Error: invalid user \"%s\".\n",val); return 1; }
                    }
                    i++;
                    continue;
                }
            }
        }else{
            char *p=arg+1;
            int consumed_next=0;
            const char *pending_val=NULL;
            int has_pending_val=0;
            // For simplicity, handle cluster by iterating, but for required args we need to handle remainder
            while (*p){
                char c=*p;
                if (c=='C'||c=='M'||c=='t'||c=='U'){
                    p++; continue;
                }else if (c=='d'){
                    const char *val=NULL;
                    if (*(p+1)!='\0'){ val=p+1; }
                    else{
                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        val=argv[i+1];
                        consumed_next=1;
                    }
                    if (!validate_delay(val)){ fprintf(stderr,"Error: invalid delay value \"%s\".\n",val); return 1; }
                    break;
                }else if (c=='F'){
                    const char *val=NULL;
                    if (*(p+1)!='\0') val=p+1;
                    else{
                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        val=argv[i+1];
                        consumed_next=1;
                    }
                    if (!validate_filter(val)){ fprintf(stderr,"Error: invalid filter value \"%s\".\n",val); return 1; }
                    break;
                }else if (c=='h'){ printf("%s",help_text); return 0; }
                else if (c=='H'){
                    const char *val=NULL;
                    int has_val=0;
                    if (*(p+1)!='\0'){ val=p+1; has_val=1; }
                    else{
                        if (i+1<argc){
                            const char *next=argv[i+1];
                            if (next[0]=='\0') has_val=0;
                            else if (next[0]=='-') has_val=0;
                            else { val=next; has_val=1; consumed_next=1; }
                        }
                    }
                    if (has_val && !validate_delay(val)){ fprintf(stderr,"Error: invalid highlight delay value \"%s\".\n",val); return 1; }
                    break;
                }else if (c=='n'){
                    const char *val=NULL;
                    if (*(p+1)!='\0') val=p+1;
                    else{
                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        val=argv[i+1];
                        consumed_next=1;
                    }
                    int inv,nonpos;
                    if (!validate_max_iter(val,&inv,&nonpos)){
                        if (inv) fprintf(stderr,"Error: invalid maximum iteration count \"%s\".\n",val);
                        else fprintf(stderr,"Error: maximum iteration count must be positive.\n");
                        return 1;
                    }
                    break;
                }else if (c=='p'){
                    // pid: no validation, break after consuming
                    if (*(p+1)=='\0' && i+1<argc){
                        // next token is arg (even empty? but empty token would be "" and we treat as arg for pid)
                        // For pid, empty string is allowed, but for optional-like handling, we should consume next even if empty? Original for -p "" gave CURSES, so empty is consumed.
                        // So if next exists, consume it regardless of starting with '-'? For required arg, yes.
                        // For -p, if next token is "--help" (starts with -), should it be consumed as pid? Original: -p --help gave CURSES, so yes consumed as pid arg? Actually earlier we saw -p --help => CURSES (not help). So required arg consumes even option-like.
                        consumed_next=1;
                    }
                    break;
                }else if (c=='s'){
                    const char *val=NULL;
                    if (*(p+1)!='\0') val=p+1;
                    else{
                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        val=argv[i+1];
                        consumed_next=1;
                    }
                    int res=is_valid_sort_key(val);
                    if (res==2){ printf("%s",sort_help_text); return 0; }
                    else if (res==0){ fprintf(stderr,"Error: invalid column \"%s\".\n",val); return 1; }
                    break;
                }else if (c=='u'){
                    const char *val=NULL;
                    int has_val=0;
                    if (*(p+1)!='\0'){ val=p+1; has_val=1; }
                    else{
                        if (i+1<argc){
                            const char *next=argv[i+1];
                            if (next[0]=='\0') has_val=0;
                            else if (next[0]=='-') has_val=0;
                            else { val=next; has_val=1; consumed_next=1; }
                        }
                    }
                    if (has_val){
                        int res=validate_user(val);
                        if (res!=1){ fprintf(stderr,"Error: invalid user \"%s\".\n",val); return 1; }
                    }
                    break;
                }else if (c=='V'){ printf("%s",version_text); return 0; }
                else{ fprintf(stderr,"%s: invalid option -- '%c'\n",progname,c); return 1; }
            }
            if (consumed_next) i++;
            i++;
            continue;
        }
    }
    const char *term=getenv("TERM");
    if (!term || strcmp(term,"unknown")==0 || strlen(term)==0){
        fprintf(stderr,"Error opening terminal: unknown.\n");
        return 1;
    }
    return 0;
}
