                }
            }
        }else{
            // short cluster
            char *p=arg+1;
            int consumed_next=0;
            while (*p){
                char c=*p;
                if (c=='C'||c=='M'||c=='t'||c=='U'){
                    p++; continue;
                }else if (c=='d'){
                    const char *val=NULL;
                    if (*(p+1)!='\0') val=p+1;
                    else{
                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        val=argv[i+1];
                        consumed_next=1;
                    }
                    if (!validate_delay(val)){ fprintf(stderr,"Error: invalid delay value \"%s\".\n",val); return 1; }
