                }else if (c=='n'){
                    const char *val=NULL;
                    if (*(p+1)!='\0') val=p+1;
                    else{
                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        val=argv[i+1];
                        consumed_next=1;
                    }
                    int inv,nonpos;
                    if (!validate_max_iter(val,&inv,&nonpos)){
                        if (inv) fprintf(stderr,"Error: invalid maximum iteration count \"%s\".\n",val);
