                    }
                    break;
                }else if (c=='p'){
                    if (*(p+1)=='\0'){
                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        // pid required arg, but may be empty string? Empty string as next token is considered arg (as per original, -p "" gave CURSES). So even if next token is empty string, we should consume it.
                        // However our earlier check for optional args skipped empty, but for required we should consume even empty.
