                        if (i+1>=argc){ fprintf(stderr,"%s: option requires an argument -- '%c'\n",progname,c); return 1; }
                        val=argv[i+1];
                        consumed_next=1;
                    }
                    int res=is_valid_sort_key(val);
                    if (res==2){ printf("%s",sort_help_text); return 0; }
                    else if (res==0){ fprintf(stderr,"Error: invalid column \"%s\".\n",val); return 1; }
                    break;
                }else if (c=='u'){
                    const char *val=NULL;
                    int has_val=0;
                    if (*(p+1)!='\0'){ val=p+1; has_val=1; }
                    else{
                        if (i+1<argc){
                            const char *next=argv[i+1];
                            if (next[0]=='\0') has_val=0;
                            else if (next[0]=='-') has_val=0;
                            else { val=next; has_val=1; consumed_next=1; }
                        }
                    }
                    if (has_val){
                        int res=validate_user(val);
                        if (res!=1){ fprintf(stderr,"Error: invalid user \"%s\".\n",val); return 1; }
