                }
            }else{
                char *p=a+1;
                int consumed=0;
                while (*p){
                    char c=*p;
                    if (c=='C'||c=='M'||c=='t'||c=='U'){ p++; continue; }
                    else if (c=='d'||c=='F'||c=='n'||c=='s'){
