                        break;
                    }else if (c=='H'||c=='u'){
                        if (*(p+1)!='\0') break;
                        else{
                            if (j+1<argc){
                                const char *next=argv[j+1];
                                if (next[0]=='\0') break;
                                else if (next[0]=='-') break;
                                else { consumed=1; break; }
                            }else break;
                        }
                    }else if (c=='h'||c=='V'){
