        // Eg., nonopts = ["", "extra"] => join with space => " extra" (since "" + " " + "extra" = " extra"). Then final message "Error: unsupported non-option ARGV-elements:  extra\n" (colon space + " extra" = two spaces before extra) matches observed.
        // If single empty: [""] => join => "" (empty) => message "Error: unsupported non-option ARGV-elements: \n" (colon space + "" = one space) matches observed for empty.
        // If ["foo","bar"] => "foo bar"

        // Build joined string
        char joined[4096]="";
